import{_ as i,c as t,o as a,ae as o}from"./chunks/framework.BGWP4WZ_.js";const p=JSON.parse('{"title":"Local TTS Feature Description for Xiaozhi AI","description":"","frontmatter":{},"headers":[],"relativePath":"guide/TTS_Functionality_Guide.md","filePath":"guide/TTS_Functionality_Guide.md"}'),n={name:"guide/TTS_Functionality_Guide.md"};function s(l,e,r,c,d,u){return a(),t("div",null,e[0]||(e[0]=[o('<h1 id="local-tts-feature-description-for-xiaozhi-ai" tabindex="-1">Local TTS Feature Description for Xiaozhi AI <a class="header-anchor" href="#local-tts-feature-description-for-xiaozhi-ai" aria-label="Permalink to &quot;Local TTS Feature Description for Xiaozhi AI&quot;">​</a></h1><h2 id="feature-overview" tabindex="-1">Feature Overview <a class="header-anchor" href="#feature-overview" aria-label="Permalink to &quot;Feature Overview&quot;">​</a></h2><p>Xiaozhi AI now supports local Text-to-Speech (TTS) functionality, allowing users to directly read specified text in the command-line interface. This feature is based on Pyttsx3 and can be used offline, providing high-quality Chinese speech synthesis.</p><h2 id="technical-implementation" tabindex="-1">Technical Implementation <a class="header-anchor" href="#technical-implementation" aria-label="Permalink to &quot;Technical Implementation&quot;">​</a></h2><ul><li>Uses the Pyttsx3 engine to generate speech</li><li>Supports quick triggering in the command line</li><li>Speech data is sent to the local audio device for playback</li><li>Enables fully local text reading functionality</li></ul><h2 id="usage-instructions" tabindex="-1">Usage Instructions <a class="header-anchor" href="#usage-instructions" aria-label="Permalink to &quot;Usage Instructions&quot;">​</a></h2><h3 id="using-in-command-line-mode" tabindex="-1">Using in Command-Line Mode <a class="header-anchor" href="#using-in-command-line-mode" aria-label="Permalink to &quot;Using in Command-Line Mode&quot;">​</a></h3><p>In command-line mode, use the following command to trigger the TTS feature:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Your desired text to send</span></span></code></pre></div><p>For example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello, Xiaozhi</span></span></code></pre></div><p>After execution, the system will convert the input text into speech and play it.</p><h3 id="usage-tips" tabindex="-1">Usage Tips <a class="header-anchor" href="#usage-tips" aria-label="Permalink to &quot;Usage Tips&quot;">​</a></h3><ol><li><strong>Long Text Reading</strong>: Supports reading longer texts, including punctuation marks.</li><li><strong>Volume Control</strong>: Adjust the volume using the <code>v number</code> command, e.g., <code>v 80</code>.</li><li><strong>Interrupt Reading</strong>: To interrupt the current reading, use the <code>x</code> command.</li><li><strong>Concurrency Control</strong>: If the current reading is not finished, new TTS requests will automatically queue.</li></ol><h2 id="dependency-information" tabindex="-1">Dependency Information <a class="header-anchor" href="#dependency-information" aria-label="Permalink to &quot;Dependency Information&quot;">​</a></h2><p>This feature depends on the following Python libraries:</p><ul><li>edge-tts: Python interface for Microsoft Edge TTS engine</li><li>soundfile: Audio file processing</li><li>pydub: Audio conversion and processing</li><li>numpy: Data processing</li></ul><h2 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h2><ol><li><p><strong>No Sound Playback</strong>:</p><ul><li>Check if the system audio device is functioning properly.</li><li>Ensure the volume is set appropriately (adjust using commands like <code>v 80</code>).</li><li>Verify that the necessary audio drivers are installed on the system.</li></ul></li><li><p><strong>Slow TTS Generation</strong>:</p><ul><li>The first use may require downloading the voice model, which can take some time.</li><li>Ensure a stable network connection (Edge TTS requires internet access).</li><li>Processing longer texts may take more time.</li></ul></li><li><p><strong>Sound Quality Issues</strong>:</p><ul><li>The default voice is &quot;zh-CN-XiaoxiaoNeural&quot; female voice from Microsoft Edge TTS.</li><li>To use other voices, modify the <code>voice</code> parameter in the source code.</li></ul></li></ol>',19)]))}const m=i(n,[["render",s]]);export{p as __pageData,m as default};
